let found = [];
for (const sheet of document.styleSheets) {
  let rules;
  try { rules = sheet.cssRules; } catch(e) { continue; }
  for (const r of rules) {
    if (r.selectorText && r.selectorText.includes('.pay')) {
      found.push({selector: r.selectorText, cssText: r.cssText, href: sheet.href});
    }
  }
}
JSON.stringify(found);

